style.css:
/* chatgpt mobile dark renk override */

body,
html {
  background-color: #0d0f10 !important; /* koyu siyah-gri */
  color: #ffffff !important;            /* beyaz yazı */
}

/* varsa kart / panel gibi açık kutular için hafif koyu gri */
div, section, article, header, footer, main, aside, nav {
  background-color: transparent;
  color: #ffffff;
}

/* input / textarea / button yazısı da beyaz olsun */
input, textarea, button {
  background-color: #1a1c1f !important; /* parlak siyah kutu tonu */
  color: #ffffff !important;
  border-color: rgba(255,255,255,0.14) !important;
}
